export class StrategicBriefing {
    /**
     * Get the current state of this project's strategic briefing
     *
     * Get the current state of this project's strategic briefing — the synthesized, as-of competitive read (what changed and what it means). This is the ANALYZED briefing; for the raw monitoring data use the per-dimension dashboards (e.g. `/pricing`), and for the monitored-competitor roster use `/competitors`.
     *
     * **This returns the LATEST run, whatever state it is in.** `meta.status` is that run's raw lifecycle status and is the field to branch on:
     *
     * - `done` — the run finished. `item`, `coverage`, `contains` and `tickets` are populated; this is the readable edition.
     * - `running` — a briefing is being generated right now. `item` is null; `meta.progress` carries the step it is on and when it started. A run finishes within two hours — budget rather than busy-wait. Treat it as running until this status changes, and never infer that a run is late or failed from how long it has taken.
     * - `failed` — the most recent attempt ended without producing an edition. `item` is null.
     * - `null` — this project has never had a briefing run at all. **This is the only value that means the project genuinely has nothing.**
     *
     * **When `meta.status` is not `done`, THIS RUN has no content — which says nothing about whether the project has a briefing.** A previously published edition is usually still readable: call `GET /v1/projects/{projectId}/strategic-briefing/history` to list the editions and `…/history/{runId}` to read one. **Never report that no briefing is available on the strength of a null `item` — check history first.**
     *
     * A missing or non-accessible project returns 404 `project_not_found`; the briefing lifecycle itself never 404s.
     *
     * **Sections — lean by default.** `sections` selects what to return and defaults to `["hub"]` — the executive digest AND the navigation map. A hub `diagnosis` row that earned a deep-dive carries a `deepDive` pointer naming the dimension to read next — prefix it with `deep-` to form the section value (a pointer of `ai-visibility` → request `sections=deep-ai-visibility`). A row without one has no deep-dive this edition and its `note` says why; request a section only for a pointer that is present. Valid sections: `hub`, `competitors`, the fourteen `deep-<dimension>` deep-dives, or `all` for the full document. Charts are off by default (`includeCharts=false` returns each chart's title + note only); pass `includeCharts=true` for the full data series.
     *
     * **What the edition recommends doing is not a section.** Every move in the edition lands on the project's Strategic Tickets board — as a new ticket, most important first, or on the ticket already there for that work (`tickets.alreadyOnBoard`). New tickets land in the `triage` column, and the team moves them from there; each carries the dimension and the estimate of the work where the edition gave them. Read the ones it opened with `GET /v1/projects/{projectId}/tickets?origin=briefing&briefingRunId={runId}`, taking `{runId}` from `meta.runId`. They are the team's from that moment: moving, editing or dismissing one changes the board, not the edition.
     *
     * **Returned with any finished edition, regardless of `sections`:** `coverage` (methodology and data-quality caveats — read these before quoting any figure), `contains` (the list of sections this edition actually holds, so you can pick what to fetch next instead of requesting slots blind), and `tickets` (how many tickets this edition opened on the board and how many of them sit in each column, counted as you read). All three are null whenever `meta.status` is not `done`, which says nothing about whether earlier editions exist — check `…/history`.
     *
     * **Reading the numbers:** the AI Visibility Score is 0–100 (higher is better); AI-visibility `presence` is the share of answers analysed that named a brand (higher is named more often) and is always read with its range; on a ticket this edition opened, `impact` is 1–4 (higher is more critical) and `briefing.estimatedMinutes` is the edition's own estimate of the work, `null` where it gave none — report that as unsized rather than as quick. A project's next briefing is scheduled roughly 30 days after its last run.
     */
    public static publicBriefingControllerGetStrategicBriefingV1<ThrowOnError extends boolean = false>(options: Options<PublicBriefingControllerGetStrategicBriefingV1Data, ThrowOnError>) {
        return (options.client ?? client).get<PublicBriefingControllerGetStrategicBriefingV1Responses, PublicBriefingControllerGetStrategicBriefingV1Errors, ThrowOnError>({
            security: [{ name: 'CL-API-Key', type: 'apiKey' }],
            url: '/v1/projects/{projectId}/strategic-briefing',
            ...options
        });
    }
    
    /**
     * List this project's briefing editions
     *
     * List this project's Strategic Briefing runs, newest first — one cheap metadata row each, never briefing content.
     *
     * Each row carries `runId` (pass it to `…/history/{runId}` to read that edition in full), `briefingDate`, `status`, the derived `editionNumber`, and `headline` — that edition's one-line verdict, so you can pick which one to open without fetching every one.
     *
     * **Runs that failed or are still generating are included**, with `editionNumber`, `briefingDate` and `headline` null. A gap between two editions is therefore explained rather than left unexplained.
     *
     * Use this to answer "what did we say in April", to trace how a read has changed over time, or — when `GET /strategic-briefing` reports a `running` or `failed` status — to find the last edition that is actually readable. For the current state use `GET /strategic-briefing`, not this.
     *
     * Paginated with `page` and `limit`; check `pagination.hasMore` to fetch further pages. Briefings are produced roughly monthly, so this list is typically short.
     */
    public static publicBriefingControllerGetStrategicBriefingHistoryV1<ThrowOnError extends boolean = false>(options: Options<PublicBriefingControllerGetStrategicBriefingHistoryV1Data, ThrowOnError>) {
        return (options.client ?? client).get<PublicBriefingControllerGetStrategicBriefingHistoryV1Responses, PublicBriefingControllerGetStrategicBriefingHistoryV1Errors, ThrowOnError>({
            security: [{ name: 'CL-API-Key', type: 'apiKey' }],
            url: '/v1/projects/{projectId}/strategic-briefing/history',
            ...options
        });
    }
    
    /**
     * Get one briefing edition by id
     *
     * Get one strategic briefing edition by `runId`, in exactly the same shape as `GET /strategic-briefing`.
     *
     * Take the `runId` from `GET /strategic-briefing/history` (or from `meta.runId` on a current read). Accepts the same `sections` and `includeCharts` options, with the same `["hub"]` default.
     *
     * A `runId` naming a run that failed or is still generating returns **200** with `meta.status` set accordingly and `item` null — that run genuinely produced no edition, which is an answer rather than an error. A malformed id returns 400 `invalid_run_id`; an id that does not belong to this project returns 404 `run_not_found`.
     *
     * Use this to read or quote a specific past edition. For the current state use `GET /strategic-briefing`.
     */
    public static publicBriefingControllerGetStrategicBriefingEditionV1<ThrowOnError extends boolean = false>(options: Options<PublicBriefingControllerGetStrategicBriefingEditionV1Data, ThrowOnError>) {
        return (options.client ?? client).get<PublicBriefingControllerGetStrategicBriefingEditionV1Responses, PublicBriefingControllerGetStrategicBriefingEditionV1Errors, ThrowOnError>({
            security: [{ name: 'CL-API-Key', type: 'apiKey' }],
            url: '/v1/projects/{projectId}/strategic-briefing/history/{runId}',
            ...options
        });
    }
}

